    out = [row[:] for row in grid]
    # A horizontal guide bar's non-1 colored cell projects upward; its color
    # caps a three-cell vertical stem in color 1.
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color not in (2, 8):
                continue
            # Restrict anchors to a horizontal guide row containing color 1s.
            if 1 not in row:
                continue
            top = max(0, r - 3)
            out[top][c] = color
            for rr in range(top + 1, r):
                out[rr][c] = 1
    return out
